import{_ as t,o as n,c as a,l as o,t as r,N as s}from"./chunks/framework.Bbd9fWQx.js";const b=JSON.parse('{"title":"env | x-cmd man (man1) | run a program in a modified environment","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | env - run a program in a modified environment","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"env | x-cmd man (man1) | run a program in a modified environment"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | env - run a program in a modified environment"}]]},"headers":[],"params":{"isMan":true,"man":"env","category":"man1","desc":"run a program in a modified environment"},"relativePath":"man1/env.md","filePath":"man1/env.md"}'),i={name:"man1/env.md"},d={class:"visually-hidden"},l=s(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>env - run a program in a modified environment</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>env</strong> [<em>OPTION</em>]... [<em>-</em>] [<em>NAME=VALUE</em>]... [*COMMAND *[<em>ARG</em>]...]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Set each NAME to VALUE in the environment and run COMMAND.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-i</strong>, <strong>--ignore-environment</strong></dt><dd>start with an empty environment</dd><dt><strong>-0</strong>, <strong>--null</strong></dt><dd>end each output line with NUL, not newline</dd><dt><strong>-u</strong>, <strong>--unset</strong>=<em>NAME</em></dt><dd>remove variable from the environment</dd><dt><strong>-C</strong>, <strong>--chdir</strong>=<em>DIR</em></dt><dd>change working directory to DIR</dd><dt><strong>-S</strong>, <strong>--split-string</strong>=<em>S</em></dt><dd>process and split S into separate arguments; used to pass multiple arguments on shebang lines</dd><dt><strong>--block-signal</strong>[=<em>SIG</em>]</dt><dd>block delivery of SIG signal(s) to COMMAND</dd><dt><strong>--default-signal</strong>[=<em>SIG</em>]</dt><dd>reset handling of SIG signal(s) to the default</dd><dt><strong>--ignore-signal</strong>[=<em>SIG</em>]</dt><dd>set handling of SIG signal(s) to do nothing</dd><dt><strong>--list-signal-handling</strong></dt><dd>list non default signal handling to stderr</dd><dt><strong>-v</strong>, <strong>--debug</strong></dt><dd>print verbose information for each processing step</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>A mere - implies <strong>-i</strong>. If no COMMAND, print the resulting environment.</p><p>SIG may be a signal name like &#39;PIPE&#39;, or a signal number like &#39;13&#39;. Without SIG, all known signals are included. Multiple signals can be comma-separated. An empty SIG argument is a no-op.</p><h3 id="exit-status" tabindex="-1">Exit status: <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;Exit status:&quot;">​</a></h3><dl><dt>125</dt><dd>if the env command itself fails</dd><dt>126</dt><dd>if COMMAND is found but cannot be invoked</dd><dt>127</dt><dd>if COMMAND cannot be found</dd><dt>-</dt><dd>the exit status of COMMAND otherwise</dd></dl><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><h3 id="s-split-string-usage-in-scripts" tabindex="-1">-S/--split-string usage in scripts <a class="header-anchor" href="#s-split-string-usage-in-scripts" aria-label="Permalink to &quot;-S/\\--split-string usage in scripts&quot;">​</a></h3><p>The <strong>-S</strong> option allows specifying multiple parameters in a script. Running a script named <strong>1.pl</strong> containing the following first line:</p><blockquote><pre><code>#!/usr/bin/env -S perl -w -T
...
</code></pre></blockquote><p>Will execute <strong>perl -w -T 1.pl .</strong></p><p>Without the <strong>&#39;-S&#39;</strong> parameter the script will likely fail with:</p><blockquote><pre><code>/usr/bin/env: &#39;perl -w -T&#39;: No such file or directory
</code></pre></blockquote><p>See the full documentation for more details.</p><h3 id="default-signal-sig-usage" tabindex="-1">--default-signal[=SIG] usage <a class="header-anchor" href="#default-signal-sig-usage" aria-label="Permalink to &quot;\\--default-signal\\[=SIG\\] usage&quot;">​</a></h3><p>This option allows setting a signal handler to its default action, which is not possible using the traditional shell trap command. The following example ensures that seq will be terminated by SIGPIPE no matter how this signal is being handled in the process invoking the command.</p><blockquote><pre><code>sh -c &#39;env --default-signal=PIPE seq inf | head -n1&#39;
</code></pre></blockquote><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>POSIX&#39;s <strong>exec</strong>(3p) pages says:</p><blockquote><p>&quot;many existing applications wrongly assume that they start with certain signals set to the default action and/or unblocked.... Therefore, it is best not to block or ignore signals across execs without explicit reason to do so, and especially not to block signals across execs of arbitrary (not closely cooperating) programs.&quot;</p></blockquote><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Richard Mlynarik, David MacKenzie, and Assaf Gordon.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>sigaction</strong>(2), <strong>sigprocmask</strong>(2), <strong>signal</strong>(7)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/env%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/env\\</a>&gt; <br> or available locally via: info &#39;(coreutils) env invocation&#39;</p>`,35);function g(e,p,h,c,m,u){return n(),a("div",null,[o("h1",d,r(e.$params.man),1),l])}const S=t(i,[["render",g]]);export{b as __pageData,S as default};
